// The webhook wraps the posted JSON under 'body'
const data = $json.body || $json;

const event = data.event_type;
const biz = data.business_name || 'Our Business';
const name = data.customer_name;
const phone = data.customer_phone;
const customerEmail = data.customer_email || '';
const time = data.appointment_time;
const ownerEmail = data.owner_email;

// Each Meta-approved template has its own variable order/count
const templates = {
  booking_confirmed: { name: 'apptbook_confirmed', params: [name, biz, time] },
  appointment_reminder: { name: 'apptbook_reminder', params: [name, biz, time] },
  booking_completed: { name: 'apptbook_completed', params: [name, biz] },
  booking_cancelled: { name: 'apptbook_cancelled', params: [name, biz, time] },
  cancellation_requested: { name: 'apptbook_cancel_request', params: [name, time] },
  cancellation_rejected: { name: 'apptbook_cancel_declined', params: [name, biz, time] }
};

const ownerSubjects = {
  booking_confirmed: `New booking confirmed - ${name}`,
  appointment_reminder: `Reminder due - ${name}`,
  booking_completed: `Booking completed - ${name}`,
  booking_cancelled: `Booking cancelled - ${name}`,
  cancellation_requested: `ACTION NEEDED: ${name} wants to cancel - approve or reject in the dashboard`,
  cancellation_rejected: `Cancellation rejected - ${name} stays booked`
};

const customerMessages = {
  booking_confirmed: {
    subject: `Your appointment with ${biz} is confirmed`,
    body: `Hi ${name},\n\nYour appointment with ${biz} on ${time} is confirmed.\n\nSee you then!`
  },
  appointment_reminder: {
    subject: `Reminder: your appointment with ${biz}`,
    body: `Hi ${name},\n\nJust a reminder that your appointment with ${biz} is on ${time}.\n\nSee you soon!`
  },
  booking_completed: {
    subject: `Thanks for visiting ${biz}`,
    body: `Hi ${name},\n\nThanks for visiting ${biz}! We hope to see you again soon.`
  },
  cancellation_requested: {
    subject: `We received your cancellation request`,
    body: `Hi ${name},\n\nWe've received your request to cancel your ${time} appointment with ${biz}. We'll confirm shortly.`
  },
  booking_cancelled: {
    subject: `Your appointment has been cancelled`,
    body: `Hi ${name},\n\nYour appointment with ${biz} on ${time} has been cancelled as requested.`
  },
  cancellation_rejected: {
    subject: `Your appointment still stands`,
    body: `Hi ${name},\n\nWe were unable to cancel your ${time} appointment with ${biz}. It still stands - see you then!`
  }
};

const tpl = templates[event] || templates.booking_confirmed;
const custMsg = customerMessages[event] || customerMessages.booking_confirmed;

return [{
  json: {
    customer_phone: phone,
    customer_email: customerEmail,
    owner_email: ownerEmail,
    whatsapp_template: tpl.name,
    whatsapp_params: tpl.params,
    owner_subject: ownerSubjects[event] || `Booking update - ${name}`,
    owner_body: `Event: ${event}\nCustomer: ${name}\nPhone: ${phone}\nAppointment: ${time}`,
    customer_subject: custMsg.subject,
    customer_body: custMsg.body
  }
}];
